  ('gibds-do-a-liachd', 'Gibds do a Liachd?', '', '', '', '', 'Gibt''s da ein Licht?', '[{"kategorie": "wörtlich", "text": "\"Gibt es hier Licht?\"  2. Gibt es hier Strom?  3. Gibt es hier eine Lichtquelle?"}]'::jsonb, ''),
  ('ewigs-liachd', 'ewigs Liachd', '', '', '', '', 'ewiges Licht', '[{"kategorie": "wörtlich, religiös", "text": "\"immerwährendes Licht\" (als Zeichen der Gegenwart Gottes)"}, {"kategorie": "\"Licht, das Tag und Nacht brennt\"", "text": "Kerzenlicht, Petroleumlicht, etc."}, {"kategorie": "scherzhaft für", "text": "Klolicht, Toilettenbeleuchtung, WC-Licht"}]'::jsonb, ''),
  ('draussn-woas-scho-liachd', 'Draussn woas scho liachd!', '', '', '', '', 'Draußen war es schon licht!', '[{"kategorie": "", "text": "Draußen war es schon hell!  2. Draußen war es bereits taghell!"}]'::jsonb, ''),
  ('da-fleck-is-beim-putzn-zwoa-liachda-wuan-owa-ned-gaunz-aussegaungan', 'Da Fleck is beim Putzn zwoa liachda wuan, owa ned gaunz aussegaungan!', '', '', '', '', 'Der Fleck ist beim Putzen zwar lichter geworden, aber nicht ganz rausgegangen!', '[{"kategorie": "", "text": "Der Fleck ist beim Putzen zwar heller geworden, aber nicht ganz rausgegangen!  2. Der Fleck hat sich zwar aufgehellt, ist aber nicht vollständig verschwunden!"}]'::jsonb, ''),
  ('liaba-heid-ois-muang', 'Liaba heid ois muang!', '', '', '', '', 'Lieber heute als morgen!', '[{"kategorie": "", "text": "Besser heute als morgen!  2. Gleich ist besser als später! (die Steigerungsform \"liaba\" wird im Wienerischen zumeist mit der Bedeutung \"besser\" verwendet"}]'::jsonb, ''),
  ('aum-liabstn-goa-ned', 'Aum liabstn goa ned!', '', '', '', '', 'Am liebsten gar nicht!', '[{"kategorie": "", "text": "Am besten gar nicht!  2. Tunlichst gar nicht! (die Steigerungsform \"liaba\" wird im Wienerischen zumeist mit der Bedeutung \"besser\" verwendet"}]'::jsonb, ''),
  ('na-sei-so-liab', 'Na sei so liab!', '', '', '', '', 'Na, sei so lieb!', '[{"kategorie": "wörtlich", "text": "Na, sei so gut!  2. (ironisch negativ): Tu mir das nicht an!  3. Bitte verschone mich!"}]'::jsonb, ''),
  ('liab-schau-ma-aus', 'Liab schau ma aus!', '', '', '', '', 'Lieb schauen wir aus!', '[{"kategorie": "ironisch negativ", "text": "Jetzt sehen wir alt aus!   2. Jetzt schauen wir dumm aus der Wäsche!  3. Jetzt sitzen wir in der Klemme!"}]'::jsonb, ''),
  ('des-is-ma-no-liaba', 'Des is ma no liaba!', '', '', '', '', 'Das ist mir noch lieber!', '[{"kategorie": "wörtlich", "text": "Das ist noch besser für mich!  2. (ironisch negativ): Das kommt noch dazu!  3. Das geht mir noch mehr gegen den Strich!  4. Das ist mir noch mehr zuwider!"}]'::jsonb, ''),
  ('du-bist-ma-no-liaba', 'Du bist ma no liaba!', '', '', '', '', 'Du bist mir noch lieber!', '[{"kategorie": "wörtlich", "text": "Du bist mir vielleicht einer!  2. (ironisch negativ): Gerade von dir hätte ich so etwas nicht erwartet!  3. Ausgerechnet du machst so was!"}]'::jsonb, ''),
  ('es-warad-ma-liaba-waunns-de-gosch-hoidst', 'Es warad ma liaba, waunns de Gosch hoidst!', '', '', '', '', 'Es wäre mir lieber, wenn du die Goschen hältst!', '[{"kategorie": "", "text": "Es wäre mir angenehmer, wenn du den Mund hältst!  2. Es wäre besser, wenn du schweigst!"}]'::jsonb, ''),
  ('gee-sei-so-liab-und-bring-ma-no-a-achtal', 'Gee sei so liab und bring ma no a Achtal!', '', '', '', '', 'Geh, sei so lieb und bring mir noch ein Achterl!', '[{"kategorie": "", "text": "Geh, sei so nett und bring mir noch ein Achtel Wein!  2. Wärst du bitte so freundlich und holst mir noch ein Achtel Wein?"}]'::jsonb, ''),
  ('ea-is-a-liabkind-von-da-zeidung', 'Ea is a Liabkind von da Zeidung!', '', '', '', '', 'Er ist ein Liebkind der Presse!', '[{"kategorie": "", "text": "Er ist ein Liebkind der Medien!  2. Die Presse ist ihm stets wohlgesonnen!"}]'::jsonb, ''),
