  ('gimma-drei-lilane', 'Gimma drei Lilane!', '', '', '', '', 'Gib mir drei Lilane!', '[{"kategorie": "wörtlich", "text": "\"Gib mir drei Violette!\"  2. Gib mir drei 500-Euro-Geldscheine! (in Anspielung auf deren violette Färbung)"}, {"kategorie": "", "text": "Gib mit 1.500 Euro!"}]'::jsonb, ''),
