  ('am-mooda-wiara-woif-haum', 'am Mooda wiara Woif haum', '', '', '', '', 'einen Marder wie ein Wolf haben', '[{"kategorie": "", "text": "einen Hunger wie ein Wolf haben"}, {"kategorie": "", "text": "einen Bärenhunger haben"}, {"kategorie": "", "text": "einen [[Mordshunger]] haben, einen [[Batzenhunger]] haben, einen [[Viechhunger]] haben"}]'::jsonb, ''),
