  ('mia-krochd-da-moong', 'Mia krochd da Moong!', '', '', '', '', 'Mir kracht der Magen!', '[{"kategorie": "", "text": "Mir knurrt der Magen!  2. Ich habe einen [[Mordshunger]]!  3. Mein Magen knurrt wie ein Bär!"}]'::jsonb, ''),
  ('do-gheada-a-moong-dazua', 'Do gheada a Moong dazua!', '', '', '', '', 'Da gehört dir ein Magen dazu!', '[{"kategorie": "", "text": "Da darf man keinen empfindlichen Magen haben!  2. Das muss man erst mal verdauen können!"}]'::jsonb, ''),
