  ('muelli-sei', 'Mülli sei', '', '', '', '', 'Mülli sein', '[{"kategorie": "wörtlich", "text": "\"in der Tretmühle sein\" (eigtl. von \"Mühle\", verballhornt zu \"Mülli\" [Koseform des Namens \"Müller\"] - in Anspielung darauf, dass es in [[Arbeitshäusern]] einst viele zu bedienende Tretmühlen gab)"}, {"kategorie": "Gaunersprache", "text": "hinter Gittern sein, festgesetzt sein, eine Haftstrafe verbüßen, im [[Häfen]] dunsten"}]'::jsonb, ''),
