  ('si-is-bei-mia-auf-mia-nix-dia-nix-eizong', 'Si is bei mia auf mia nix, dia nix eizong!', '', '', '', '', 'Sie ist bei mir auf mir nichts, dir nichts eingezogen!', '[{"kategorie": "", "text": "Sie ist bei mir ohne jede Vorwarnung eingezogen!  2. Sie ist bei mir wie aus heiterem Himmel eingezogen!"}]'::jsonb, ''),
  ('dem-wearis-mischn', 'Dem wearis mischn!', '', '', '', '', 'Dem werde ich es mischen!', '[{"kategorie": "", "text": "Dem werde ich unverblümt die Wahrheit sagen!  2. Dem werde ich die volle Wahrheit unter die Nase reiben!  3. Dem werde ich die nackte Wahrheit präsentieren!"}]'::jsonb, ''),
