  ('en-oasch-mit-dia', 'En Oasch mit dia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In den Arsch mit dir!', '[{"kategorie": "wörtlich", "text": "\"Scher dich zum Teufel!\"  2. \"Verpiss dich!\"  3. \"Geh dorthin, wo der Pfeffer wächst!\"  4. [[Schleich]] di!  5. [[Vazupf]] di!  6. [[Putz]] di!  7. [[Gee]] scheissn!  8. [[Hau]] di in Rettich!  9. [[Moch]] Määta!  10. [[Gee]] päule!  11. [[Loss]] di eipanian!"}]'::jsonb, ''),
  ('bei-den-kenn-i-mi-ned-aus-den-kaunnsd-aafoch-ned-in-schaeaedl-eineschaun', 'Bei den kenn I mi ned aus - den kaunnsd aafoch ned in Schäädl eineschaun!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei dem kenne ich mich nicht aus - dem kannst du einfach nicht in den Schädel reinschauen!', '[{"kategorie": "wörtlich", "text": "\"Bei dem Typen kenne ich mich nicht aus - dem kann man einfach nicht in den Kopf hineinschauen!\"  2. Mit dem werde ich einfach nicht schlau – man weiß nie, was in dem vorgeht!  3. Ich komm bei dem einfach nicht klar – bei dem weiß man nie, woran man ist!"}]'::jsonb, ''),
  ('den-muassd-neema-wiara-is-den-kriagsd-nii-aufd-rei', 'Den muassd neema, wiara is - den kriagsd nii aufd Rei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Den musst du nehmen, wie er ist – den kriegst du nie auf die Reihe!', '[{"kategorie": "wörtlich", "text": "\"Den musst du nehmen, wie er ist – den bringst du nie auf Linie!\"  2. Den kriegst du nicht gebogen – also nimm ihn, wie er ist!  3. Den kannst du nicht umpolen – den musst du akzeptieren, wie er ist!"}]'::jsonb, ''),
  ('deena-wea-ma-heid-eischenkn', 'Deena wea ma heid eischenkn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Denen werden wir heute einschenken!', '[{"kategorie": "wörtlich", "text": "\"Denen schenken wir heute ordentlich ein!\"  2. Denen nageln wir heute ein paar Dinger rein!  3. Denen zeigen wir heute, wo der Hammer hängt!"}]'::jsonb, ''),
  ('deena-jungan-ghead-de-zukunft-und-deena-oidn-da-respekt', 'Deena Jungan ghead de Zukunft, und deena Oidn da Respekt!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Den Jungen gehört die Zukunft, und den Alten der Respekt!', '[{"kategorie": "wörtlich", "text": "\"Den Jungen gehört das Morgen, den Alten die Ehre!\"  2. Den Jungen die Bühne, den Alten der Applaus!  3. Den Jungen gehört die Welt von morgen, den Alten die Achtung von heute!"}]'::jsonb, ''),
  ('deenan-eanare', 'deenan eanare', '', '', '', 'Grundwortschatz Wienerisch', 'denen ihre', '[{"kategorie": "wörtlich", "text": "\"denen ihre\" (dialektale, possessive Dativkonstruktion - doppelte Besitzanzeige, die grammatisch unsauber, aber umgangssprachlich durchaus üblich ist, vom mittelhochdeutschen \"dënen ire\" = \"deren\")"}, {"kategorie": "allg.", "text": "\"deren\", \"ihre\""}]'::jsonb, 'Deenan eanare Gschroppn san de äagstn Rotzpiipn!'),
  ('deenan-eanare-gschroppn-san-de-aeagstn-rotzpiipn', 'Deenan eanare Gschroppn san de äagstn Rotzpiipn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Denen ihre G''schrappen sind die ärgsten Rotzpipen!', '[{"kategorie": "wörtlich", "text": "\"Deren Kinder sind die ärgsten Rotznasen!\"  2. Die Bälger von denen sind die schlimmsten Rotzlöffel, die du dir vorstellen kannst!  3. Deren Sprösslinge sind derartige Rotzbengel, dass Worte nicht ausreichen!"}]'::jsonb, 'deenan eanare'),
  ('deenan-wea-ma-heid-eischenkn', 'Deenan wea ma heid eischenkn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Denen werden wir heute einschenken!', '[{"kategorie": "wörtlich", "text": "\"Denen schenken wir heute ordentlich ein!\"  2. Denen nageln wir heute ein paar Dinger rein!  3. Denen zeigen wir heute, wo der Hammer hängt!"}]'::jsonb, ''),
  ('deenan-jungan-ghead-de-zukunft-und-deenan-oidn-da-respekt', 'Deenan Jungan ghead de Zukunft, und deenan Oidn da Respekt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Den Jungen gehört die Zukunft, und den Alten der Respekt!', '[{"kategorie": "wörtlich", "text": "\"Den Jungen gehört das Morgen, den Alten die Ehre!\"  2. Den Jungen die Bühne, den Alten der Applaus!  3. Den Jungen gehört die Welt von morgen, den Alten die Achtung von heute!"}]'::jsonb, ''),
  ('dera-muassd-in-goeoedhau-zuadraan', 'Dera muassd in Göödhau zuadraan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der musst du den Geldhahn zudrehen!', '[{"kategorie": "wörtlich", "text": "\"Der musst du den Geldfluss abdrehen!\"  2. Der darfst du keinen einzigen Cent mehr geben!  3. Der musst du den Geldhahn zudrehen, bevor sie dich trockenlegt!"}]'::jsonb, ''),
  ('dera-iare', 'dera iare', '', '', '', 'Grundwortschatz Wienerisch', 'der ihre', '[{"kategorie": "wörtlich", "text": "\"die von ihr\" (dialektale, possessive Dativkonstruktion - doppelte Besitzanzeige, die grammatisch unsauber, aber umgangssprachlich durchaus üblich ist, vom mittelhochdeutschen \"dër ire\" = \"deren\")"}, {"kategorie": "allg.", "text": "\"deren\", \"ihre\", \"die von ihr\""}]'::jsonb, ''),
  ('dera-iare-gschroppn-san-de-aeagstn-rotzpiipn', 'Dera iare Gschroppn san de äagstn Rotzpiipn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der ihre G''schrappen sind die ärgsten Rotzpipen!', '[{"kategorie": "wörtlich", "text": "\"Ihre Kinder sind die ärgsten Rotznasen!\"  2. Die Dreikäsehochs von ihr sind die schlimmsten Rotzlöffel, die du dir vorstellen kannst!  3. Ihre Sprösslinge sind derartige Rotzbengel, dass Worte nicht ausreichen!"}]'::jsonb, ''),
  ('dera-ia', 'dera ia', '', '', '', 'Grundwortschatz Wienerisch', 'der ihr', '[{"kategorie": "wörtlich", "text": "\"der/die/das von ihr\" (dialektale, possessive Dativkonstruktion - doppelte Besitzanzeige, die grammatisch unsauber, aber umgangssprachlich durchaus üblich ist, vom mittelhochdeutschen \"dër ir\" = \"deren\")"}, {"kategorie": "allg.", "text": "\"deren\", \"ihr/ihre\", \"der/die/das von ihr\""}]'::jsonb, 'Dera ia Gschau gfoid ma goa ned!'),
  ('dera-ia-gschau-gfoid-ma-goa-ned', 'Dera ia Gschau gfoid ma goa ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ihr Geschaue gefällt mir gar nicht!', '[{"kategorie": "wörtlich", "text": "\"Der Gesichtsausdruck von ihr gefällt mir gar nicht!\"  2. Ihre Miene lässt auf nichts Gutes schließen!  3. Der Blick von ihr spricht Bände - der gefällt mir gar nicht!"}]'::jsonb, 'dera ia'),
  ('den-sei', 'den sei', '', '', '', 'Grundwortschatz Wienerisch', 'dem sein', '[{"kategorie": "wörtlich", "text": "\"der/die/das von ihm\" (dialektale, possessive Dativkonstruktion - doppelte Besitzanzeige, die grammatisch unsauber, aber umgangssprachlich durchaus üblich ist, vom mittelhochdeutschen \"dën sein\" = \"dessen\")"}, {"kategorie": "allg.", "text": "\"dessen\", \"sein/seine/seines\", \"der/die/das von ihm\""}]'::jsonb, 'Den sei Zeit wiad aa noo kumman!'),
  ('den-sei-zeit-wiad-aa-noo-kumman', 'Den sei Zeit wiad aa noo kumman!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dem seine Zeit wird auch noch kommen!', '[{"kategorie": "wörtlich", "text": "\"Seine Zeit wird auch noch kommen!\"  2. Auch er wird noch seine Chance bekommen!  3. Der Stern von ihm wird auch noch aufgehen!"}]'::jsonb, ''),
  ('den-seine', 'den seine', '', '', '', 'Grundwortschatz Wienerisch', 'dem seine', '[{"kategorie": "wörtlich", "text": "\"die von ihm\" (dialektale, possessive Dativkonstruktion - doppelte Besitzanzeige, die grammatisch unsauber, aber umgangssprachlich durchaus üblich ist, vom mittelhochdeutschen \"dën seine\" = \"dessen\")"}, {"kategorie": "allg.", "text": "\"dessen\", \"seine\", \"die von ihm\""}]'::jsonb, 'Den seine Schmää san olle fian Oasch!'),
  ('den-seine-schmaeae-san-olle-fian-oasch', 'Den seine Schmää san olle fian Oasch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dem seine Schmäh sind alle für''n Arsch!', '[{"kategorie": "wörtlich", "text": "\"Seine Sprüche sind einfach alle nur daneben!\"  2. Der Humor von ihm ist unterste Schublade!  3. Die [[Wuchteln]] von ihm gehen allen sowas von am Arsch vorbei!"}]'::jsonb, 'den seine'),
  ('wo-seids-ia-gweesn', 'Wo seids ia gweesn?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Wo seid ihr gewesen?', '[{"kategorie": "wörtlich", "text": "\"Wo habt ihr euch rumgetrieben?\"  2. Wo habt ihr gesteckt?  3. Was habt ihr denn die ganze Zeit gemacht?"}]'::jsonb, ''),
  ('es-beste-is-ned-aufmuckn', 'Es Beste is ned aufmuckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Beste ist, nicht aufzumucken!', '[{"kategorie": "wörtlich", "text": "\"Das Beste ist, nicht aufzubegehren!\"  2. Am klügsten ist es, den Mund zu halten!  3. Das Beste ist, keine Wellen zu schlagen!"}]'::jsonb, ''),
  ('s-beste-is-ned-aufmuckn', 's Beste is ned aufmuckn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Beste ist, nicht aufzumucken!', '[{"kategorie": "wörtlich", "text": "\"Das Beste ist, nicht aufzubegehren!\"  2. Am klügsten ist es, den Mund zu halten!  3. Das Beste ist, keine Wellen zu schlagen!"}]'::jsonb, ''),
  ('is-da-wos', 'Is da wos?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ist dir was?', '[{"kategorie": "wörtlich", "text": "\"Ist etwas mit dir?\"  2. \"Alles okay bei dir?\"  3. \"Stimmt was nicht?\"  4. \"Ist dir eine Laus über die Leber gelaufen?\""}]'::jsonb, ''),
  ('da1', 'da1', '', '', '', 'Grundwortschatz Wienerisch', 'dir', '[{"kategorie": "wörtlich", "text": "\"dir\" (Personalpronomen, 2. Person Singular, Dativ - unbetontes \"dir\" - im Gegensatz zu [[dia]] = betontes \"dir\")"}, {"kategorie": "allg.", "text": "\"dir\" (unbetontes, fließendes „dir“, wird in vielen Fällen statt à„dia“ im Alltag verwendet"}, {"kategorie": "\"Dativus ethicus\" = emotionaler Dativ, der nicht grammatisch notwendig ist", "text": "\"dir\""}]'::jsonb, 'Des Loob gebüad dia, ned eam!'),
  ('i-bin-da-wos-grantig', 'I bin da wos grantig!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich bin dir was grantig!', '[{"kategorie": "wörtlich", "text": "\"Ich bin ziemlich sauer (auf dich), und du sollst das gefälligst merken!\" (\"dir\" als \"Dativus ethicus\" = emotionaler Dativ, der nicht grammatisch notwendig ist)"}, {"kategorie": "", "text": "Ich bin dir ziemlich gram – und ich hoffe, dass dir das bewusst ist!  3. Ich bin dir echt gram  – und das sollst du ruhig auch wissen!"}]'::jsonb, ''),
  ('da2', 'da2', '', '', '', 'Grundwortschatz Wienerisch', 'der', '[{"kategorie": "wörtlich", "text": "\"der\" (männlicher bestimmter Artikel)"}, {"kategorie": "allg.", "text": "\"der\", \"dieser\", \"der da\""}]'::jsonb, ''),
  ('da-3', 'da-3', '', '', '', 'Grundwortschatz Wienerisch', 'der-', '[{"kategorie": "wörtlich", "text": "\"der-\" (Präfix, abgeleitet vom mittelhochdeutschen „zer-“, das wiederum auf das germanische \"tera-\"zurückgeht - altes germanisches Erbwortgut, das sich in der Dialektsprache erhalten hat und ursprünglich \"auseinander\" bzw. \"in Stücke\" bedeutete. Es ist eine alte Nebenform von „zer-“, also ein trennendes, auflösendes, oft destruktives Präfix, das in Wiener Dialektwörtern meist zur Verstärkung dient, aber auch eine resultative oder perfektive Bedeutung in sich trägt, d.h. die Handlung wird vollendet, abgeschlossen, oder führt zu einem klaren Ergebnis)"}, {"kategorie": "allg.", "text": "\"zer-\", \"er-\""}]'::jsonb, ''),
  ('der', 'der-', '', '', '', 'Grundwortschatz Wienerisch', 'der-', '[{"kategorie": "wörtlich", "text": "\"der-\" (Präfix, abgeleitet vom mittelhochdeutschen „darr-“, das wiederum auf das germanische \"tera-\"zurückgeht - altes germanisches Erbwortgut, das sich in der Dialektsprache erhalten hat und ursprünglich \"auseinander\" bzw. \"in Stücke\" bedeutete. Es ist eine alte Nebenform von „zer-“, also ein trennendes, auflösendes, oft destruktives Präfix, das in Wiener Dialektwörtern meist zur Verstärkung dient, aber auch eine resultative oder perfektive Bedeutung in sich trägt, d.h. die Handlung wird vollendet, abgeschlossen, oder führt zu einem klaren Ergebnis)"}, {"kategorie": "allg.", "text": "\"zer-\", \"er-\", \"auf-\""}]'::jsonb, 'si dawuuzln'),
  ('dar', 'dar-', '', '', '', 'Grundwortschatz Wienerisch', 'dar-', '[{"kategorie": "wörtlich", "text": "\"dar-\" (Präfix, abgeleitet vom mittelhochdeutschen „darr-“, das wiederum auf das germanische \"tera-\"zurückgeht - altes germanisches Erbwortgut, das sich in der Dialektsprache erhalten hat und ursprünglich \"auseinander\" bzw. \"in Stücke\" bedeutete. Es ist eine alte Nebenform von „zer-“, also ein trennendes, auflösendes, oft destruktives Präfix, das in Wiener Dialektwörtern meist zur Verstärkung dient, aber auch eine resultative oder perfektive Bedeutung in sich trägt, d.h. die Handlung wird vollendet, abgeschlossen, oder führt zu einem klaren Ergebnis)"}, {"kategorie": "allg.", "text": "\"zer-\", \"er-\", \"auf-\""}]'::jsonb, ''),
  ('ma1', 'ma1', '', '', '', 'Grundwortschatz Wienerisch', 'mir', '[{"kategorie": "wörtlich", "text": "\"mir\" (Personalpronomen, 1. Person Singular, Dativ - unbetontes \"mir\" - im Gegensatz zu [[mia]] = betontes \"mir\")"}, {"kategorie": "allg.", "text": "\"mir\" (unbetontes, fließendes „mir“, wird in vielen Fällen statt à„mia“ im Alltag verwendet"}, {"kategorie": "\"Dativus ethicus\" = emotionaler Dativ, der nicht grammatisch notwendig ist", "text": "\"mir\""}]'::jsonb, 'Gibs mia, ned eam!'),
  ('dea-kummd-ma-ned-gaunz-kooscha-vua', 'Dea kummd ma ned gaunz kooscha vua!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der kommt mir nicht ganz koscher vor!', '[{"kategorie": "wörtlich", "text": "\"Mir kommt der nicht ganz astrein vor!\"  2. Mir ist der irgedwie suspekt!  3. Der ist mir nicht ganz geheuer!"}]'::jsonb, ''),
  ('du-bist-ma-viileichd-a-schlawiina', 'Du bist ma viileichd a Schlawiina!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du bist mir vielleicht ein Schlawiner!', '[{"kategorie": "wörtlich", "text": "\"Du bist mir vielleicht ein Schlitzohr!\"  2. Na, du bist mir vielleicht ein Fuchs!  3. Du bist mir ja ein ganz Schlauer, du!"}]'::jsonb, ''),
  ('ned-dassd-ma-vom-fleisch-foisd', 'Ned, dassd ma vom Fleisch foisd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nicht, dass du mir vom Fleisch fällst!', '[{"kategorie": "wörtlich", "text": "\"Nicht, dass du mir von den Rippen fällst!\"  2. \"Nicht, dass du mir noch verhungerst!\"  3. Damit du mir nur ja nicht verschmachtest!"}]'::jsonb, ''),
  ('dassd-ma-ned-owefoist-von-da-laata', 'Dassd ma ned owefoist von da Laata!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dass du mir nicht runterfällst von der Leiter!', '[{"kategorie": "wörtlich", "text": "\"Fall mir bloß nicht von der Leiter runter!\"  2. Pass mir auf, dass du nicht von der Leiter runterfällst!  3. Bitte gib mir Acht, dass du nicht von der Leiter fällst!"}]'::jsonb, ''),
  ('du-bist-ma-viilleichd-aana', 'Du bist ma viilleichd aana!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du bist mir vielleicht einer!', '[{"kategorie": "wörtlich", "text": "\"Du bist mir aber auch ein Kerl!\"  2. Du bist mir ja ein ganz Schlauer, du!  3. Du machst mir vielleicht Sachen, also ehrlich!"}]'::jsonb, ''),
  ('ma-leidln-so-geebds-doch-endlich-a-rua', 'Ma, Leidln, so geebds doch endlich a Rua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ma, Leute, so gebt doch endlich eine Ruhe!', '[{"kategorie": "", "text": "Um Himmels willen, Leute, so gebt doch endlich Ruhe!  2. Also wirklich, Leute, seid nicht so lästig!  3. Bei meiner Treu, könnt ihr nicht endlich Ruhe geben?"}]'::jsonb, ''),
  ('ma3', 'Ma3', '', '', '', 'Grundwortschatz Wienerisch', 'Ma', '[{"kategorie": "wörtlich", "text": "\"Ma\" (Diskursmarker am Satzanfang, vom slawischen/italienischen \"ma\"=\"aber\" - hat sich im Wienerischen aber eigenständig entwickelt und wird emotional, interaktiv oder betonend eingesetzt)"}, {"kategorie": "allg.", "text": "\"Ach\", \"Na komm\", \"Komm schon\", \"Hör auf\", \"Also wirklich\", \"bei meiner Treu\", \"Na bitte\""}]'::jsonb, 'Ma, Leidln, so geebds doch endlich a Rua!'),
  ('ma-seids-ned-so', 'Ma, seids ned so!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ma, seid nicht so!', '[{"kategorie": "wörtlich", "text": "\"Kommt schon, seid nicht so empfindlich!\"  2. Also wirklich, stellt euch nicht so an!  3. Hört auf, so zu tun, als wär’s ein Drama!"}]'::jsonb, ''),
  ('ma2', 'ma2', '', '', '', '', 'man', '[{"kategorie": "wörtlich", "text": "\"man\" (Indefinitpronomen, 3. Person Singular, Nominativ)"}, {"kategorie": "allg.", "text": "\"man\", (oft pauschalisierend): \"die Leute\", \"alle\""}]'::jsonb, ''),
  ('ma-schdruudld-si-a-leebm-laung-oo-und-froogd-si-aum-end-fia-wos', 'Ma schdruudld si a Leebm laung oo - und froogd si aum End: ''Fia wos''?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Man strudelt sich ein Leben lang ab - und fragt sich am Ende: ''Für was?''', '[{"kategorie": "wörtlich", "text": "\"Man rackert sich ein ganzes Leben lang ab – und am Ende fragt man sich: Wofür?\"  2. Man schuftet sein ganzes Leben lang – und fragt sich dann irgendwann: Wozu das Ganze?  3. Man lebt, strebt, arbeitet – und fragt sich zum Schluss: War’s das wert?"}]'::jsonb, 'si ooschdruudln'),
  ('ma4', 'ma4', '', '', '', 'Grundwortschatz Wienerisch', 'wir', '[{"kategorie": "wörtlich", "text": "\"wir\" (Personalpronomen, 1. Person Plural, Nominativ - \"unbetontes wir\" - im Gegensatz zu [[mia]]=\"betontes wir\")"}, {"kategorie": "allg.", "text": "\"wir\" (unbetontes, fließendes „wir“, wird in vielen Fällen statt „mia“ im Alltag verwendet"}]'::jsonb, 'Mia - und ned de aundan!'),
  ('do-hoda-mi-gsund-einelossn', 'Do hoda mi gsund einelossn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da hat er mich gesund reingelassen!', '[{"kategorie": "wörtlich", "text": "\"Da hat er mich sauber reingelegt!\"  2. Da hat er mich richtig vorgeführt!  3. Da hat er mich aber ordentlich verarscht!"}]'::jsonb, ''),
  ('ka-idee', 'Ka Idee!', '', '', '', '', 'Keine Idee!', '[{"kategorie": "", "text": "Keine Ahnung!  2. Kein Plan!  3. Frag mich was Leichteres!"}]'::jsonb, ''),
  ('ka-idee-wos-i-song-soi', 'Ka Idee, wos I song soi!', '', '', '', '', 'Keine Idee, was ich sagen soll!', '[{"kategorie": "", "text": "Ich weiß im Moment nicht, was ich sagen soll!  2. Mir fehlen im Moment die Worte!  3. Im Moment fällt mir nichts ein!"}]'::jsonb, ''),
  ('ka-idee-haum', 'ka Idee haum', '', '', '', '', 'keine Idee haben', '[{"kategorie": "", "text": "keine Ahnung haben"}, {"kategorie": "", "text": "keine Vorstellung von etwas haben"}, {"kategorie": "", "text": "sich keinen Reim auf etwas machen können"}, {"kategorie": "", "text": "völlig ratlos sein"}]'::jsonb, ''),
  ('host-a-idee', 'Host a Idee?', '', '', '', '', 'Hast du eine Idee?', '[{"kategorie": "", "text": "Fällt dir dazu was ein?  2. Was denkst du?  3. Was würdest du vorschlagen?"}]'::jsonb, ''),
  ('du-host-jo-ka-idee-wos-ma-gestan-passiad-is', 'Du host jo ka Idee, wos ma gestan passiad is!', '', '', '', '', 'Du hast ja keine Idee, was mir gestern passiert ist!', '[{"kategorie": "", "text": "Du hast ja nicht die leiseste Ahnung, was mir gestern passiert ist!  2. Du kannst dir gar nicht vorstellen, was mir gestern passiert ist!"}]'::jsonb, ''),
  ('ned-amoi-ignorian', 'Ned amoi ignorian!', '', '', '', '', 'Nicht einmal ignorieren!', '[{"kategorie": "", "text": "\"Gar nicht erst hinschauen!  2. Bloß nicht reagieren!  3. Tu so, als wäre er/sie/es Luft!  (Zur Erklärung: Indem man jemanden \"nicht einmal ignoriert\", bringt man dem Betreffenden ein Höchstmaß an Verachtung entgegen)"}]'::jsonb, '')
